package main

import (
	"context"
	"encoding/json"
	"log"
	"os"

	"github.com/jepsen-io/maelstrom/demo/go"
)

func handleInit(ctx context.Context, node go.Node, body map[string]interface{}) {
	node.Reply(ctx, go.Body{Type: "init_ok"})
}

type addReq struct {
	Type      string `json:"type"`
	InReplyTo int64  `json:"in_reply_to,omitempty"`
	Delta     int64  `json:"delta"`
}

type addOk struct {
	Type       string `json:"type"`
	MsgID      int64  `json:"msg_id"`
	InReplyTo  int64  `json:"in_reply_to,omitempty"`
	Result     int64  `json:"result,omitempty"`
	Delta      int64  `json:"delta,omitempty"`
}

type readReq struct {
	Type       string `json:"type"`
	InReplyTo  int64  `json:"in_reply_to,omitempty"`
	MsgID      int64  `json:"msg_id"`
}

type readOk struct {
	Type      string `json:"type"`
	MsgID     int64  `json:"msg_id"`
	InReplyTo int64  `json:"in_reply_to,omitempty"`
	Value     int64  `json:"value"`
}

func handleAdd(ctx context.Context, node go.Node, body map[string]interface{}) {
	// Get the request JSON from body and unmarshal it into a proper struct to extract fields correctly
	var req addReq
	if rawBody, ok := body["body"].(string); ok {
		jsonBytes := []byte(rawBody)
		if err := json.Unmarshal(jsonBytes, &req); err != nil {
			node.Reply(ctx, go.Body{Type: "err", Body: map[string]interface{}{"error": err.Error()}})
			return
		}
	} else {
		jsonBytes, _ := json.Marshal(body["body"])
		if err := json.Unmarshal(jsonBytes, &req); err != nil {
			node.Reply(ctx, go.Body{Type: "err", Body: map[string]interface{}{"error": err.Error()}})
			return
		}
	}

	// Create a seq-kv tied to this node's ID for the counter
	seqKV := node.NewSeqKV(node.ID())

	// Use compare-and-swap to atomically update our contribution to the counter
	key := "counter" // We can use a simple key since it's per-node

	current, success, err := seqKV.CompareAndSwap(ctx, key, req.Delta)
	if err != nil {
		log.Printf("Error in CAS: %v", err)
		node.Reply(ctx, go.Body{Type: "err", Body: map[string]interface{}{"error": err.Error()}})
		return
	}

	if !success {
		log.Println("CAS failed")
		// Try a simple write as fallback - seq-kv.Write is atomic at the store level
		writeResult, err := seqKV.Write(ctx, key, req.Delta)
		if err != nil {
			log.Printf("Write error: %v", err)
			node.Reply(ctx, go.Body{Type: "err", Body: map[string]interface{}{"error": err.Error()}})
			return
		}
		current = writeResult.Value
	}

	// Extract message ID from the original request body
	msgID := -1
	if rawBodyStr, ok := body["msg_id"].(string); ok {
		jsonBytes, _ := json.Marshal(body["body"])
		var req2 map[string]interface{}
		json.Unmarshal(jsonBytes, &req2)
		if rid, ok := req2["msg_id"].(float64); ok {
			msgID = int64(rid)
		}
	}

	node.Reply(ctx, go.Body{
		Type:       "add_ok",
		MsgID:      msgID,
		InReplyTo:  req.InReplyTo,
		Result:     current,
		Delta:      req.Delta,
	})
}

func handleRead(ctx context.Context, node go.Node, body map[string]interface{}) {
	seqKV := node.NewSeqKV(node.ID())

	key := "counter"
	value, _, err := seqKV.ReadInt(ctx, key)
	if err != nil {
		log.Printf("Error in read: %v", err)
		node.Reply(ctx, go.Body{Type: "err", Body: map[string]interface{}{"error": err.Error()}})
		return
	}

	msgID := -1
	if rawBodyStr, ok := body["msg_id"].(string); ok {
		jsonBytes, _ := json.Marshal(body["body"])
		var req2 map[string]interface{}
		json.Unmarshal(jsonBytes, &req2)
		if rid, ok := req2["msg_id"].(float64); ok {
			msgID = int64(rid)
		}
	}

	node.Reply(ctx, go.Body{
		Type:    "read_ok",
		MsgID:   msgID,
		InReplyTo: -1,
		Value:   value,
	})
}

func main() {
	ctx := context.Background()

	node := maelstrom.NewNode(ctx)

	seqKV := node.NewSeqKV(node.ID())

	maelstrom.Handle(node, "init", handleInit)
	maelstrom.Handle(node, "add", handleAdd)
	maelstrom.Handle(node, "read", handleRead)

	if err := node.Run(); err != nil {
		log.Fatalf("node.Run() failed: %v", err)
	}
}

